'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>Array.from(root.querySelectorAll(s));
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n=>'S/ '+Number(n).toLocaleString('es-PE',{maximumFractionDigits:0});
const today = ()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const dateLabel = s=>new Date(s+'T12:00:00').toLocaleDateString('es-PE',{day:'numeric',month:'long',year:'numeric'});
const datePlus=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const destination = id=>MYSTIGO_DESTINATIONS.find(d=>d.id===id);
const mapLink=(place,city)=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(place+', '+city+', '+(MYSTIGO_DESTINATIONS.find(d=>d.name===city)?.country||'Perú'));
const paths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3z"/><path d="M9 3v15M15 6v15"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5"/>',mountain:'<path d="m2 20 7-14 5 9 3-6 5 11z"/><path d="m6 12 3 2 3-2"/>',culture:'<path d="m3 8 9-5 9 5H3ZM5 11v7M10 11v7M15 11v7M20 11v7M2 21h20"/>',leaf:'<path d="M20 3C8 1 1 10 6 17c7 7 17-1 14-14Z"/><path d="M4 21 16 9M10 15h6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M21 7H5a3 3 0 0 1 0-6h14v6M3 4v16h18V7M16 11h5v5h-5z"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v14H3z"/><circle cx="12" cy="13" r="4"/>',food:'<path d="M4 3v7a3 3 0 0 0 6 0V3M7 3v19M20 22V3c-5 0-5 11 0 11"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>',check:'<path d="m4 12 5 5L20 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 17v4h18v-4"/>',plane:'<path d="m22 2-7 20-4-9L2 9zM22 2 11 13"/>'};
const icon = n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.map}</svg>`;
const categoryIcon={Todos:'search',Playa:'sun',Naturaleza:'leaf',Aventura:'mountain',Cultura:'culture',Gastronomía:'food',Fotografía:'camera',Descanso:'sun'};
const KEY='mystigo.v1';
const defaults=()=>({profile:null,prefs:{types:[],activities:[],company:'En pareja',budget:'Moderado'},favorites:[],selected:[],plans:[],events:[],opinions:[],notifications:[],notificationPrefs:{inApp:true,device:false,sound:true},affinity:{},surpriseHistory:[]});
let state=defaults(),storageAvailable=true,currentPlan=null,toastTimer,explore={q:'',category:'Todos',zone:'Todas',budget:'Todos'};
try{const value=JSON.parse(localStorage.getItem(KEY)||'null');if(value&&typeof value==='object'){state={...defaults(),...value,prefs:{...defaults().prefs,...value.prefs}};for(const k of ['favorites','selected','plans','events','opinions'])if(!Array.isArray(state[k]))state[k]=[];state.favorites=state.favorites.filter(id=>destination(id));state.plans=state.plans.filter(p=>p&&destination(p.dest)&&Array.isArray(p.days));}}catch{storageAvailable=false;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageAvailable=false;toast('El navegador no permite guardar más datos. Exporta tu itinerario para conservarlo.');return false;}}
function log(type,detail){state.events.unshift({type,detail,at:new Date().toISOString()});state.events=state.events.slice(0,100);persist();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
const navItems=[['inicio','home','Inicio'],['explorar','search','Explorar'],['itinerarios','map','Mis viajes'],['favoritos','heart','Favoritos'],['perfil','user','Mi perfil']];
function nav(active){const links=mobile=>navItems.map(([id,i,label])=>`<a href="#${id}" class="${mobile?'':'nav-link '}${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${!mobile&&id==='favoritos'&&state.favorites.length?`<span class="nav-count">${state.favorites.length}</span>`:''}</a>`).join('');$('#navigation').innerHTML=links(false);$('#mobile-navigation').innerHTML=links(true);const name=state.profile?.name||'Tu espacio de viajero';$('#avatar').textContent=state.profile?.name?.trim().slice(0,1).toUpperCase()||'M';$('#profile-label').innerHTML=`${esc(name)}<small>${state.profile?'Tus preferencias y viajes':'Crea tu perfil'}</small>`;$('#header-profile').innerHTML=state.profile?`Hola, ${esc(state.profile.name.split(' ')[0])} ${icon('user')}`:'Crear mi perfil <span>↗</span>';}

// Twelve independent page routes. Dialogs are used only to confirm deletion.
const SCREEN_ROUTES = Object.freeze({
  inicio:{label:'Inicio',nav:'inicio',breadcrumb:'DESCUBRE / EL MUNDO'},
  explorar:{label:'Explorar destinos',nav:'explorar',breadcrumb:'EXPLORA / DESTINOS'},
  destino:{label:'Detalles del destino',nav:'explorar',breadcrumb:'DESCUBRE / TU DESTINO'},
  itinerarios:{label:'Mis viajes sorpresa',nav:'itinerarios',breadcrumb:'PLANIFICA / TU AVENTURA'},
  plan:{label:'Mi itinerario',nav:'itinerarios',breadcrumb:'TU VIAJE / DÍA A DÍA'},
  favoritos:{label:'Favoritos',nav:'favoritos',breadcrumb:'GUARDA / INSPIRACIÓN'},
  perfil:{label:'Mi perfil',nav:'perfil',breadcrumb:'TU ESPACIO / VIAJERO'},
  ayuda:{label:'Ayuda y opiniones',nav:'ayuda',breadcrumb:'MYSTIGO / TE ACOMPAÑA'},
  registro:{label:'Crear o editar perfil',nav:'perfil',breadcrumb:'TU PERFIL / DATOS PERSONALES'},
  preferencias:{label:'Preferencias de viaje',nav:'perfil',breadcrumb:'TU PERFIL / TU FORMA DE VIAJAR'},
  solicitud:{label:'Resumen de solicitud',nav:'itinerarios',breadcrumb:'TU SOLICITUD / REVISIÓN'},
  confirmacion:{label:'Confirmación de solicitud',nav:'itinerarios',breadcrumb:'TU SOLICITUD / PRÓXIMOS PASOS'}
});
function routeInfo(){const [path,query='']=(location.hash.slice(1)||'inicio').split('?');const [page,id]=path.split('/');return {path,page,id,params:new URLSearchParams(query)};}
function safeReturn(value,fallback='inicio'){
  if(typeof value!=='string'||!value||value.length>500)return fallback;
  const path=value.split('?')[0],parts=path.split('/'),page=parts[0],id=parts[1];
  if(!SCREEN_ROUTES[page]||['registro','preferencias'].includes(page)||parts.length>2)return fallback;
  if(page==='destino'&&!destination(id))return fallback;
  if(['plan','solicitud','confirmacion'].includes(page)&&!id?.match(/^[a-zA-Z0-9_-]{1,100}$/))return fallback;
  if(!['destino','plan','solicitud','confirmacion'].includes(page)&&id)return fallback;
  return value;
}
function navigate(route){if($('#modal').open)$('#modal').close();const target='#'+route;if(location.hash===target){render();$('#main').focus({preventScroll:true});}else location.hash=target;}
function findPlan(id){return currentPlan?.id===id?currentPlan:state.plans.find(p=>p.id===id);}
function flowSteps(labels,active){return `<ol class="flow-steps" aria-label="Progreso">${labels.map((label,i)=>`<li class="${i===active?'current':i<active?'complete':''}" ${i===active?'aria-current="step"':''}><span>${i<active?'✓':i+1}</span>${label}</li>`).join('')}</ol>`;}
function pageBack(route,label){return `<a class="back-link" href="#${esc(route)}">← ${label}</a>`;}
function missingPlan(){return empty('map','Este itinerario no está en tu navegador.','Los planes se conservan en el dispositivo donde los guardaste. Puedes crear uno nuevo.','Crear mi itinerario',null,'#itinerarios');}

function card(d){const saved=state.favorites.includes(d.id);return `<article class="destination-card"><div class="card-image-wrap"><a href="#destino/${d.id}" aria-label="Descubrir ${d.name}"><img class="card-photo" src="${d.image}" alt="${esc(d.photo)}" loading="lazy"></a><span class="card-tag">${esc(d.categories[0])}</span><button class="favorite-button ${saved?'saved':''}" data-action="favorite" data-id="${d.id}" aria-label="${saved?'Quitar':'Guardar'} ${d.name} ${saved?'de':'en'} favoritos" aria-pressed="${saved}">${icon('heart')}</button></div><div class="card-body"><div class="card-place">${icon('pin')}${esc(d.region)}, ${esc(d.country||'Perú')}</div><a href="#destino/${d.id}"><h3 class="card-title">${esc(d.name)}</h3></a><p>${esc(d.description)}</p><div class="card-bottom"><span>Estimado por día<br><strong>${money(d.daily)}</strong> / persona</span><a href="#destino/${d.id}" class="round-arrow" aria-label="Ver ${d.name}">↗</a></div></div></article>`;}
function categories(active='Todos',action='explore-category'){return `<div class="categories" aria-label="Categorías de viaje">${['Todos','Playa','Naturaleza','Aventura','Cultura'].map(c=>`<button class="category ${active===c?'active':''}" data-action="${action}" data-category="${c}" aria-pressed="${active===c}">${icon(categoryIcon[c])}${c==='Todos'?'Todos los destinos':c}</button>`).join('')}</div>`;}
function title(eyebrow,heading,subtitle,extra=''){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${extra}</div>`;}
function ranked(){const t=state.prefs.types;return [...MYSTIGO_DESTINATIONS].sort((a,b)=>b.categories.filter(c=>t.includes(c)).length-a.categories.filter(c=>t.includes(c)).length);}
function home(){const first=state.profile?.name?.split(' ')[0];return `${title('NO ES SOLO VIAJAR. ES VIVIRLO.',first?`Hola, ${esc(first)}. ¿A dónde vamos?`:'Tu próxima historia empieza aquí.','Descubre un Perú que se parece a ti.',`<span class="date-tag">${icon('sun')}PERÚ, SIEMPRE POR DESCUBRIR</span>`)}<section class="hero" aria-label="Descubre el Perú"><img class="hero-image" src="cusco.jpg" alt="Machu Picchu entre las montañas de Cusco"><div class="hero-copy"><span class="hero-label">UN PAÍS. MILES DE FORMAS DE SENTIRLO.</span><h2>Llena tu vida<br>de <em>lugares.</em><br>No de pendientes.</h2><p>De la costa a los Andes, encuentra ese destino que llevas tiempo imaginando.</p><a class="button yellow" href="#explorar">Encontrar mi próxima aventura <span>↗</span></a></div><a class="hero-location" href="#destino/cusco">${icon('pin')}<span><strong>Machu Picchu</strong><small>CUSCO, PERÚ</small></span></a></section><form class="search-strip" id="home-search"><label><span class="field-caption">TU PRÓXIMA PARADA</span><input name="query" placeholder="¿A dónde quieres viajar?" aria-label="Buscar un destino"></label><label><span class="field-caption">TU FORMA DE VIAJAR</span><select name="category" aria-label="Categoría de viaje"><option value="Todos">Un poco de todo</option><option>Playa</option><option>Naturaleza</option><option>Aventura</option><option>Cultura</option></select></label><button class="button" type="submit">${icon('search')} Explorar</button></form>${categories('Todos','home-category')}<div class="section-heading"><div><h2>${state.prefs.types.length?'Elegidos para ti':'Inspírate. Elige. Escápate.'}</h2><p>${state.prefs.types.length?'Destinos que conectan con tus preferencias.':'Grandes experiencias, a tu manera.'}</p></div><a href="#explorar" class="text-link">Ver destinos ${icon('arrow')}</a></div><div class="card-grid">${ranked().slice(0,6).map(card).join('')}</div><section class="info-banner"><span class="banner-star">✦</span><div><h3>Tú eliges el destino.<br>Nosotros ordenamos la aventura.</h3><p>Itinerarios por día, actividades y un presupuesto orientativo.</p></div><div><span class="price">S/ 15</span><small>Servicio de planificación</small></div><a href="#itinerarios" class="button yellow small">Crear mi itinerario ↗</a></section><p class="storage-note">Los presupuestos son estimaciones de planificación por persona; no incluyen traslado interprovincial, vuelos ni reservas especiales. Tus perfiles, favoritos y planes se guardan en este navegador.</p>`;}
function exploreView(params){explore={q:params.get('q')||'',category:params.get('categoria')||'Todos',zone:'Todas',budget:'Todos'};return `${title('ENCUENTRA TU LUGAR','¿Qué te gustaría descubrir?','Busca por destino, región o experiencia. Tú marcas el rumbo.')}<div class="filter-row"><div class="input-wrap"><label class="field-caption" for="explore-query">DESTINO O EXPERIENCIA</label><input id="explore-query" type="search" value="${esc(explore.q)}" placeholder="Ej. Trujillo, playa, naturaleza…"></div><div class="input-wrap"><label class="field-caption" for="explore-zone">UBICACIÓN</label><select id="explore-zone"><option>Todas</option><option>Costa</option><option>Sierra</option><option>Selva</option></select></div><div class="input-wrap"><label class="field-caption" for="explore-budget">PRESUPUESTO DIARIO</label><select id="explore-budget"><option value="Todos">Todos</option><option value="100">Hasta S/ 100</option><option value="130">Hasta S/ 130</option><option value="200">Hasta S/ 200</option></select></div></div>${categories(explore.category)}<p class="results-count" id="results-count"></p><div class="card-grid" id="explore-results"></div><p class="storage-note">Estimaciones propias para comparar destinos, sin cotización ni reserva. Confirma siempre el costo y disponibilidad de cada servicio.</p>`;}
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function updateExplore(){if(!$('#explore-results'))return;const list=MYSTIGO_DESTINATIONS.filter(d=>(explore.category==='Todos'||d.categories.includes(explore.category))&&(explore.zone==='Todas'||d.zone===explore.zone)&&(explore.budget==='Todos'||d.daily<=Number(explore.budget))&&normalize([d.name,d.region,d.zone,...d.categories,d.description].join(' ')).includes(normalize(explore.q)));$('#results-count').textContent=`${list.length} ${list.length===1?'destino encontrado':'destinos encontrados'} · descubre tu próxima parada`;$('#explore-results').classList.toggle('card-grid',list.length>0);$('#explore-results').innerHTML=list.length?list.map(card).join(''):empty('search','Cada aventura tiene su lugar.','Prueba otra búsqueda o cambia los filtros para encontrar más destinos.','Restablecer filtros','reset-filters');$$('[data-action="explore-category"]').forEach(b=>{b.classList.toggle('active',b.dataset.category===explore.category);b.setAttribute('aria-pressed',b.dataset.category===explore.category);});}
function empty(i,h,p,b,action,href){return `<div class="empty">${icon(i)}<h2>${h}</h2><p>${p}</p>${href?`<a href="${href}" class="button">${b}</a>`:`<button class="button" data-action="${action}">${b}</button>`}</div>`;}
function details(d){return `<a class="back-link" href="#explorar">← Volver a los destinos</a><section class="detail-hero"><img src="${d.image}" alt="${esc(d.photo)}"><div class="detail-hero-copy"><span class="hero-label">${esc(d.region.toUpperCase())} · ${esc((d.country||'Perú').toUpperCase())}</span><h1>${esc(d.name)}</h1><p style="margin:0;font-size:13px">${esc(d.tag)}</p></div><button class="favorite-button ${state.favorites.includes(d.id)?'saved':''}" data-action="favorite" data-id="${d.id}" aria-label="Guardar o quitar ${d.name} de favoritos" aria-pressed="${state.favorites.includes(d.id)}">${icon('heart')}</button></section><div class="detail-layout"><div><section class="panel"><div class="eyebrow">DÉJATE SORPRENDER</div><h2>Un lugar, muchas historias.</h2><p>${esc(d.about)}</p><div class="chips">${d.categories.map(c=>`<span class="pill">${esc(c)}</span>`).join('')}</div></section><section class="panel"><h2>Haz espacio para estas experiencias.</h2><p>Agrega tus lugares preferidos y úsalos al planificar tu recorrido.</p>${d.blocks.flatMap((b,bi)=>b.items.filter((a,ai)=>!/^Almuerzo|Retorno|Traslado|Salida|Ingreso|Embarque|Paseo por el centro|Gastronomía/.test(a[1])).map(a=>{const ai=b.items.indexOf(a),key=`${d.id}|${bi}|${ai}`,selected=state.selected.includes(key);return `<div class="activity-card"><span class="activity-icon">${icon(categoryIcon[b.tags[0]])}</span><div class="activity-main"><h3>${esc(a[1])}</h3><p>${esc(a[2])}</p><a class="text-link" href="${mapLink(a[1],d.name)}" target="_blank" rel="noopener noreferrer">Ver en Google Maps ↗</a></div><button class="add-activity ${selected?'selected':''}" data-action="select-activity" data-key="${key}" aria-pressed="${selected}">${selected?'✓ Agregado':'+ Mi viaje'}</button></div>`;})).join('')}</section></div><aside class="detail-aside"><section class="panel"><div class="fact">${icon('wallet')}<div><small>Estimado por persona / día</small><strong>${money(d.daily)} · estilo económico</strong></div></div><div class="fact">${icon('clock')}<div><small>Una escapada de</small><strong>${d.days}</strong></div></div><div class="fact">${icon('sun')}<div><small>Antes de viajar</small><strong>${esc(d.season)}</strong></div></div><a href="#itinerarios?destino=${d.id}" class="button" style="width:100%">Crear mi itinerario ↗</a><p class="storage-note">Servicio de planificación: S/ 15. Entradas, hospedaje y transporte se contratan por separado.</p></section><section class="panel"><div class="eyebrow">UN CONSEJO PARA TU VIAJE</div><p>${esc(d.tip)}</p><a class="source-link" href="${d.source}" target="_blank" rel="noopener noreferrer">Información turística · ${d.sourceLabel} ↗</a></section></aside></div>`;}
function favoriteView(){return `${title('LOS LUGARES QUE TE LLAMAN','Tu lista de próximas historias.','Guarda hoy los destinos que quieres conocer mañana.')}<div class="${state.favorites.length?'card-grid':''}">${state.favorites.length?state.favorites.map(id=>card(destination(id))).join(''):empty('heart','Tu próxima aventura está por aparecer.','Explora los destinos y toca el corazón para guardarlos aquí.','Descubrir destinos',null,'#explorar')}</div>`;}
function planner(params){const selected=destination(params.get('destino'))?.id||'trujillo';return `${title('UN VIAJE CON TU NOMBRE','Crea tu itinerario ideal.','Un destino, tus preferencias y un recorrido para aprovechar cada día.')}<div class="planner-layout"><div><form class="panel" id="planner-form"><div class="step-label">01 / CUÉNTANOS TU IDEA</div><h2>¿Cómo imaginas tu viaje?</h2><div class="form-grid"><div class="field"><label for="plan-destination">Destino</label><select id="plan-destination" name="dest">${MYSTIGO_DESTINATIONS.map(d=>`<option value="${d.id}" ${selected===d.id?'selected':''}>${d.name} · ${d.region}</option>`).join('')}</select></div><div class="field"><label for="plan-date">Fecha de inicio</label><input id="plan-date" name="date" type="date" value="${datePlus(today(),7)}" min="${today()}" required></div><div class="field"><label for="plan-days">Duración del viaje</label><select name="days" id="plan-days">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===3?'selected':''}>${n} ${n===1?'día':'días'}</option>`).join('')}</select></div><div class="field"><label for="plan-people">Personas</label><input name="people" id="plan-people" type="number" min="1" max="20" value="1" required></div><div class="field"><label for="plan-budget">Presupuesto total del grupo (S/)</label><input name="budget" id="plan-budget" type="number" min="50" max="1000000" step="1" value="600" required></div><div class="field"><label for="plan-style">Estilo de viaje</label><select name="style" id="plan-style"><option>Económico</option><option ${state.prefs.budget==='Moderado'?'selected':''}>Moderado</option><option ${state.prefs.budget==='Alto'?'selected':''}>Alto</option></select></div><div class="field wide"><label>¿Qué te gustaría hacer?</label><div class="chips" id="plan-interests">${['Cultura','Naturaleza','Aventura','Playa','Gastronomía','Fotografía','Descanso'].map(c=>`<button type="button" class="choice" data-action="plan-interest" data-value="${c}" aria-pressed="${[...state.prefs.types,...state.prefs.activities].includes(c)}">${c}</button>`).join('')}</div></div></div><div class="selected-list" id="selected-activities"></div><div class="notice">El presupuesto cubre una estimación de alojamiento, alimentación y actividades locales. Los pasajes hacia el destino y las reservas especiales se calculan aparte.</div><div class="form-actions"><button class="button" type="submit">Generar vista previa ${icon('arrow')}</button></div></form><div id="saved-plans">${savedPlans()}</div></div><aside class="planner-aside"><section class="panel"><div class="eyebrow">DEJA ESPACIO PARA DISFRUTAR</div><h2>Un plan que va contigo.</h2><ul class="planner-benefits"><li>Actividades organizadas por día</li><li>Horarios orientativos y días editables</li><li>Recomendaciones según tus intereses</li><li>Acceso a ubicaciones en Google Maps</li><li>Presupuesto estimado del recorrido</li><li>Plan descargable para llevar contigo</li></ul><div class="summary-price"><span>Servicio de planificación</span><strong>S/ 15</strong></div><p class="storage-note">Puedes crear y guardar una vista previa. Las solicitudes comerciales quedan pendientes de pago; esta web todavía no procesa cobros.</p></section><div class="notice yellow">Cada aventura necesita su tiempo. Las excursiones largas ocupan una jornada propia y están sujetas a disponibilidad.</div></aside></div>`;}
function selectedText(dest){const keys=state.selected.filter(k=>k.startsWith(dest+'|'));const names=keys.map(k=>{const [id,b,i]=k.split('|');return destination(id)?.blocks[b]?.items[i]?.[1];}).filter(Boolean);return names.length?`Lugares que elegiste: ${names.map(esc).join(' · ')}`:'Puedes añadir lugares desde la ficha de cada destino.';}
function savedPlans(){return `<div class="section-heading"><div><h2>Mis itinerarios</h2><p>Guardados en este navegador.</p></div></div>${state.plans.length?`<div class="plan-list">${state.plans.map(p=>`<article class="saved-plan"><div><h3>${esc(destination(p.dest).name)} · ${p.days.length} días</h3><p>${dateLabel(p.date)} · ${p.people} ${p.people===1?'persona':'personas'} · ${p.status==='requested'?'Solicitud pendiente de pago':'Vista previa guardada'}</p></div><div><a href="#plan/${encodeURIComponent(p.id)}" class="button outline small">Abrir ↗</a> <button class="text-link" data-action="delete-plan" data-id="${esc(p.id)}" aria-label="Eliminar itinerario de ${esc(destination(p.dest).name)}">Eliminar</button></div></article>`).join('')}</div>`:empty('map','Todavía quedan mapas por estrenar.','Crea una vista previa y guárdala para encontrarla aquí.','Explorar destinos',null,'#explorar')}`;}
function createPlan(form){const f=new FormData(form),dest=destination(f.get('dest')),days=Number(f.get('days')),people=Number(f.get('people')),budget=Number(f.get('budget')),date=f.get('date'),style=f.get('style');if(!dest||!Number.isInteger(days)||days<1||days>7||!Number.isInteger(people)||people<1||people>20||!Number.isFinite(budget)||budget<50||budget>1000000||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date<today()){toast('Revisa el destino, la fecha y los datos de tu viaje.');return;}const interests=$$('#plan-interests .choice[aria-pressed="true"]').map(b=>b.dataset.value);const chosen=state.selected.filter(k=>k.startsWith(dest.id+'|'));const blockIds=dest.blocks.map((b,i)=>i);const score=i=>dest.blocks[i].tags.filter(t=>interests.includes(t)).length+chosen.filter(k=>Number(k.split('|')[1])===i).length*20;blockIds.splice(1,blockIds.length-1,...blockIds.slice(1).sort((a,b)=>score(b)-score(a)));const dayPlans=Array.from({length:days},(_,i)=>{const idx=blockIds[i];const b=dest.blocks[idx];return b?{title:b.title,block:idx,full:!!b.full,extra:!!b.extra,items:b.items.map(a=>({time:a[0],name:a[1],note:a[2]}))}:{title:'Un día a tu ritmo',block:null,full:false,extra:false,items:[{time:'10:00',name:'Tiempo libre en '+dest.name,note:'Personaliza esta jornada según tus intereses y lo que esté disponible.'},{time:'13:00',name:'Almuerzo y descanso',note:'Reserva tiempo para disfrutar sin prisa.'},{time:'16:00',name:'Espacio para una experiencia local',note:'Consulta alternativas con proveedores del destino.'}]};});const factor={Económico:1,Moderado:1.4,Alto:2.2}[style]||1;const base=dest.daily*factor*people;const lodging=Math.round(base*.4*Math.max(0,days-1)),food=Math.round(base*.35*days),activities=Math.round(base*.25*days),reserve=Math.round((lodging+food+activities)*.1),estimated=lodging+food+activities+reserve;currentPlan={id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),dest:dest.id,date,people,budget,style,interests,days:dayPlans,cost:{lodging,food,activities,reserve,total:estimated},status:'preview',created:new Date().toISOString(),omitted:chosen.filter(k=>!dayPlans.some(d=>d.block===Number(k.split('|')[1]))).map(k=>dest.blocks[k.split('|')[1]].items[k.split('|')[2]][1])};log('itinerario_creado',dest.name);location.hash='plan/'+currentPlan.id;}
function planView(p){const d=destination(p.dest);return `<a class="back-link" href="#itinerarios">← Volver al planificador</a><section class="plan-header"><div><div class="hero-label">TU PRÓXIMA AVENTURA, PASO A PASO</div><h1>${esc(d.name)} a tu manera.</h1><p>${dateLabel(p.date)} · ${p.days.length} días · ${p.people} ${p.people===1?'persona':'personas'} · ${esc(p.style)}</p></div><span class="pill">${p.status==='requested'?'Solicitud pendiente de pago':'Vista previa del recorrido'}</span></section><div class="budget-cards"><div class="budget-card"><small>Tu presupuesto de viaje</small><strong>${money(p.budget)}</strong></div><div class="budget-card"><small>Estimado del grupo</small><strong>${money(p.cost.total)}</strong></div><div class="budget-card"><small>Planificación por separado</small><strong>S/ 15</strong></div></div>${p.cost.total>p.budget?`<div class="notice budget-warning">El recorrido supera tu presupuesto en aproximadamente ${money(p.cost.total-p.budget)}. Prueba un estilo más económico, reduce la duración o ajusta tu presupuesto.</div>`:''}<p class="storage-note">Cálculo orientativo: alojamiento ${money(p.cost.lodging)} · alimentación ${money(p.cost.food)} · actividades y movilidad local ${money(p.cost.activities)} · margen de reserva ${money(p.cost.reserve)}. No es una cotización. Pasajes, vuelos y reservas especiales no incluidos.</p>${p.days.some(day=>day.extra)?'<div class="notice yellow spacer-top">Este plan incluye una excursión especial. El traslado, las entradas y las reservas para Machu Picchu requieren cotización y confirmación aparte; no están cubiertos por el estimado general.</div>':''}${p.omitted?.length?`<div class="notice yellow spacer-top">Estos lugares seleccionados no caben en la duración elegida: ${p.omitted.map(esc).join(', ')}. Aumenta los días para incluirlos.</div>`:''}<div class="section-heading"><div><h2>Tu recorrido, día por día.</h2><p>Horarios orientativos: adáptalos a los servicios que contrates.</p></div></div>${p.days.map((day,di)=>`<section class="day-card"><div class="day-title"><span class="day-number">${di+1}</span><div><h3>${esc(day.title)}</h3><small>${dateLabel(datePlus(p.date,di))}${day.full?' · Excursión de jornada completa':''}</small></div></div><ol class="timeline">${day.items.map((a,ai)=>`<li><time>${esc(a.time)}</time><div class="timeline-content"><h4>${esc(a.name)}</h4><p>${esc(a.note)}</p><a href="${mapLink(a.name,d.name)}" target="_blank" rel="noopener noreferrer" class="text-link">Ver ubicación ↗</a></div><div class="timeline-controls no-print"><button data-action="move-item" data-day="${di}" data-item="${ai}" data-direction="-1" ${ai===0?'disabled':''} aria-label="Mover ${esc(a.name)} arriba">↑</button><button data-action="move-item" data-day="${di}" data-item="${ai}" data-direction="1" ${ai===day.items.length-1?'disabled':''} aria-label="Mover ${esc(a.name)} abajo">↓</button><button data-action="remove-item" data-day="${di}" data-item="${ai}" aria-label="Quitar ${esc(a.name)}">×</button></div></li>`).join('')}</ol></section>`).join('')}<div class="notice">${esc(d.tip)} Verifica horarios, accesos y condiciones con cada proveedor antes del viaje.</div><div class="form-actions plan-actions"><button class="button" data-action="save-plan">Guardar itinerario ${icon('check')}</button><button class="button outline" data-action="download-plan">${icon('download')}Descargar plan</button><button class="button outline" data-action="print-plan">Imprimir / PDF</button><button class="button yellow" data-action="request-plan">Solicitar planificación · S/ 15 ↗</button></div><p class="storage-note">La solicitud se guarda en este dispositivo. Para contactar a Mystigo, podrás abrir un correo con el resumen. No hay cobro ni reserva automática.</p>`;}
function profileView(){if(!state.profile)return `${title('TU FORMA DE VIAJAR','Un espacio para tus próximas aventuras.','Guarda tus gustos y encuentra destinos que conecten contigo.')}${empty('user','Todo comienza con conocerte.','Crea un perfil local con tu nombre y correo. Tus preferencias, favoritos e itinerarios se conservarán en este navegador.','Crear mi perfil','register')}<p class="storage-note">El perfil local no es una cuenta con autenticación en un servidor. Para esta primera versión no te pedimos contraseña.</p>`;const p=state.profile;return `<div class="profile-cover"><span class="avatar">${esc(p.name[0].toUpperCase())}</span><div><div class="hero-label" style="margin-bottom:10px">TU ESPACIO EN MYSTIGO</div><h1>${esc(p.name)}</h1><p>${esc(p.email)}</p></div></div><div class="stats"><div class="stat"><strong>${state.favorites.length}</strong><small>Destinos favoritos</small></div><div class="stat"><strong>${state.plans.length}</strong><small>Itinerarios guardados</small></div><div class="stat"><strong>${state.prefs.types.length}</strong><small>Intereses de viaje</small></div></div><section class="panel"><div class="section-heading" style="margin-top:0"><h2>Tu forma de descubrir el mundo.</h2><button class="text-link" data-action="preferences">Editar preferencias ↗</button></div><div class="chips">${state.prefs.types.length?state.prefs.types.map(t=>`<span class="pill">${esc(t)}</span>`).join(''):'<span class="muted">Aún no elegiste tus intereses.</span>'}</div><p class="spacer-top">Actividades: ${state.prefs.activities.map(esc).join(', ')||'Por elegir'}<br>Compañía: ${esc(state.prefs.company)} · Presupuesto habitual: ${esc(state.prefs.budget)}</p><div class="form-actions"><button class="button outline small" data-action="edit-profile">Editar mi perfil</button><button class="button outline small" data-action="export-data">Descargar mis datos</button></div><p class="storage-note">Tu información permanece en este navegador. Puedes utilizar un perfil sin correo para explorar. No hay autenticación remota ni sincronización entre dispositivos.</p></section>${savedPlans()}<section class="panel spacer-top"><h3>Actividad reciente</h3>${state.events.slice(0,7).map(e=>`<p style="margin:8px 0;font-size:10px">${esc(e.type.replaceAll('_',' '))} · ${esc(e.detail)} <span class="muted">${new Date(e.at).toLocaleDateString('es-PE')}</span></p>`).join('')||'<p>Tu próxima historia comienza hoy.</p>'}<div class="divider"></div><button class="button danger small" data-action="reset-data">Borrar mis datos de este navegador</button></section>`;}
function helpView(){return `${title('VIAJA CON LAS COSAS CLARAS','Estamos para ayudarte.','Conoce cómo funciona Mystigo y comparte tu experiencia.')}<div class="help-layout"><div><section class="panel"><h2>Preguntas que viajan contigo.</h2>${[['¿Qué es Mystigo?','Una aplicación para descubrir destinos turísticos del Perú y organizar recorridos según tus preferencias, duración y presupuesto.'],['¿Qué incluye el servicio de S/ 15?','La propuesta de planificación organiza actividades por día, un orden de visita, horarios orientativos y un presupuesto estimado. Las entradas, el transporte, las comidas y el hospedaje se pagan por separado.'],['¿Puedo pagar o reservar en esta web?','Todavía no hay una pasarela de pago ni reservas conectadas. Puedes crear una vista previa y registrar una solicitud local pendiente de pago. El contacto por correo abre un borrador que tú decides enviar.'],['¿Dónde están mis datos?','Se guardan en el almacenamiento local de este navegador. No se envían a Mystigo ni a una base de datos central. Si borras los datos del navegador, se perderán; puedes exportarlos antes.'],['¿Los presupuestos y horarios son definitivos?','No. Son estimaciones propias de planificación. Verifica costos, disponibilidad, accesos y tiempos con los proveedores y las fuentes oficiales antes de viajar.'],['¿Hay recomendaciones con inteligencia artificial?','Esta versión organiza las sugerencias a partir de tus preferencias y un catálogo de rutas. No utiliza un servicio de inteligencia artificial externo.']].map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class="panel"><h3>Hablemos de tu próxima aventura.</h3><p>Contacto: <a class="source-link" href="mailto:mytigo.maps@gmail.com">mytigo.maps@gmail.com</a></p><a class="button outline small" href="mailto:mytigo.maps@gmail.com?subject=Consulta%20MYSTIGO">Abrir mi correo ↗</a><p class="storage-note">Abre tu aplicación de correo; revisa y envía el mensaje si deseas contactar con Mystigo.</p></section><section class="panel"><h3>Fuentes y créditos</h3><p>El contenido general se apoya en las fuentes turísticas oficiales enlazadas para cada destino. La disponibilidad debe confirmarse antes de viajar.</p>${MYSTIGO_DESTINATIONS.map(d=>`<p style="margin:6px 0"><a class="source-link" href="${d.source}" target="_blank" rel="noopener noreferrer">${d.sourceLabel} ↗</a></p>`).join('')}<p class="photo-credit">Fotografías internacionales: Wikimedia Commons; autor y licencia en cada ficha y en el README del repositorio. Fotografías de Perú: Unsplash, HOLA, Huaraz Turismo, Assist Card, Diario El Pueblo, Despegar y TPP Perú. Créditos y enlaces en el README. Logo proporcionado por MYSTIGO.</p></section></div><div><form class="panel" id="opinion-form"><div class="eyebrow">TU EXPERIENCIA NOS AYUDA</div><h2>¿Qué tal va la aventura?</h2><p>Deja una opinión en tu dispositivo o prepara un correo para compartirla con Mystigo.</p><input type="hidden" name="rating" value="0"><div class="rating" role="group" aria-label="Calificación de la experiencia">${[1,2,3,4,5].map(n=>`<button type="button" data-action="rating" data-rating="${n}" aria-label="${n} estrellas" aria-pressed="false">★</button>`).join('')}</div><div class="stack spacer-top"><div class="field"><label for="opinion-name">Nombre</label><input id="opinion-name" name="name" maxlength="80" value="${esc(state.profile?.name||'')}" required></div><div class="field"><label for="opinion-message">Tu comentario o consulta</label><textarea id="opinion-message" name="message" maxlength="1500" required placeholder="Cuéntanos qué te gustó o qué podemos mejorar…"></textarea></div></div><div class="form-actions"><button class="button" type="submit">Guardar mi opinión</button></div><p class="storage-note">Este formulario no envía información automáticamente. Después de guardarla puedes abrir un correo para compartirla.</p></form><section class="panel"><h3>Mis opiniones guardadas</h3>${state.opinions.length?state.opinions.map(o=>`<article class="opinion"><strong>${esc(o.name)} <span style="color:#dba600">${'★'.repeat(Math.max(0,Math.min(5,Number(o.rating)||0)))}</span></strong><p>${esc(o.message)}</p><small>Guardada en este navegador · ${new Date(o.at).toLocaleDateString('es-PE')}</small><br><a class="text-link" href="mailto:mytigo.maps@gmail.com?subject=Opini%C3%B3n%20sobre%20MYSTIGO&body=${encodeURIComponent(`${o.name}\nCalificación: ${o.rating}/5\n\n${o.message}`)}">Compartir por correo ↗</a></article>`).join(''):'<p>Tus comentarios aparecerán aquí. No son reseñas públicas.</p>'}</section></div></div>`;}
function openModal(content){$('#modal-content').innerHTML=`<div class="modal-body"><button class="close-modal" data-action="close-modal" aria-label="Cerrar ventana">×</button>${content}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function profileFormView(params){
  const edit=!!state.profile,back=safeReturn(params.get('volver'),edit?'perfil':'inicio');
  return `${pageBack(back,'Volver')}${title('TU PRÓXIMA AVENTURA COMIENZA AQUÍ',edit?'Tu perfil, a tu manera.':'Hola, viajero. Vamos a conocernos.','Un espacio propio para tus próximas historias.')}
  ${flowSteps(['Tu perfil','Tus preferencias'],0)}
  <div class="account-layout"><section class="panel account-form"><form id="profile-form" data-return="${esc(back)}"><h2>${edit?'Tus datos de viajero':'Crea tu perfil de viaje'}</h2><p>Cuéntanos cómo te llamas para acompañarte en tu próxima aventura.</p><div class="stack"><div class="field"><label for="profile-name">Nombre y apellido</label><input id="profile-name" name="name" autocomplete="name" maxlength="80" value="${esc(state.profile?.name||'')}" required></div><div class="field"><label for="profile-email">Correo electrónico</label><input id="profile-email" name="email" type="email" autocomplete="email" maxlength="160" value="${esc(state.profile?.email||'')}"></div></div><p class="storage-note">Tu perfil se guarda en este navegador. No necesitas contraseña y no se enviará ningún correo automático.</p><div class="form-actions"><button class="button" type="submit">${edit?'Guardar cambios':'Continuar a mis preferencias'} ${icon('arrow')}</button><a class="button outline" href="#${esc(back)}">Volver</a></div></form></section><aside class="account-story"><img src="cusco.jpg" alt="Machu Picchu entre montañas"><div><span class="hero-label">EL VIAJE EMPIEZA CONTIGO</span><h2>Tu nombre.<br>Tu ritmo.<br>Tu próxima historia.</h2><p>Conserva tus destinos favoritos y crea recorridos que conecten con tu forma de viajar.</p></div></aside></div>`;
}
function choices(group,values,selected){return `<div class="chips" data-choice-group="${group}">${values.map(v=>`<button type="button" class="choice" data-action="preference-choice" data-value="${v}" aria-pressed="${selected.includes(v)}">${v}</button>`).join('')}</div>`;}
function preferencesView(params,draftPrefs=state.prefs){
  const prefs=draftPrefs;
  const back=safeReturn(params.get('volver'),state.profile?'perfil':'inicio');
  return `${pageBack(back,'Volver')}${title('VIAJES QUE SE PARECEN A TI','Cuéntanos qué te mueve.','Elige tus intereses y descubre destinos que van contigo.')}
  ${flowSteps(['Tu perfil','Tus preferencias'],1)}
  <div class="account-layout"><form class="panel account-form" id="preferences-form" data-return="${esc(back)}"><h2>Tu forma de viajar.</h2><div class="stack"><fieldset class="preference-fieldset"><legend>¿Qué tipo de viajes disfrutas?</legend>${choices('types',['Playa','Naturaleza','Aventura','Cultura'],prefs.types)}</fieldset><fieldset class="preference-fieldset"><legend>¿Qué actividades prefieres?</legend>${choices('activities',['Caminatas','Deportes extremos','Gastronomía','Fotografía','Descanso'],prefs.activities)}</fieldset><div class="form-grid"><div class="field"><label for="pref-company">¿Con quién sueles viajar?</label><select id="pref-company" name="company">${['Solo','En pareja','Con amigos','En familia'].map(v=>`<option ${v===prefs.company?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="pref-budget">Presupuesto habitual</label><select id="pref-budget" name="budget">${['Económico','Moderado','Alto'].map(v=>`<option ${v===prefs.budget?'selected':''}>${v}</option>`).join('')}</select></div></div></div><div class="form-actions"><button class="button" type="submit">Guardar mis preferencias ${icon('check')}</button><a class="button outline" href="#${esc(back)}">Volver</a><button class="button outline" type="button" data-action="restart-preferences">Reiniciar</button></div></form><aside class="panel preference-story"><span class="preference-spark">✦</span><div class="eyebrow">NINGÚN VIAJE ES IGUAL</div><h2>Hay un Perú<br>para cada forma<br>de sentir.</h2><p>¿Una tarde de playa, una caminata entre montañas o sabores que nunca probaste? Tus preferencias ayudan a ordenar las recomendaciones.</p><div class="preference-illustrations">${icon('sun')}${icon('mountain')}${icon('culture')}${icon('leaf')}</div><p class="storage-note">Puedes cambiar estas preferencias cuando quieras desde Mi perfil.</p></aside></div>`;
}
function render(){
  const {page,id,params}=routeInfo();let html,screen=page;
  if(page==='inicio')html=home();
  else if(page==='explorar')html=exploreView(params);
  else if(page==='destino'&&destination(id))html=details(destination(id));
  else if(page==='favoritos')html=favoriteView();
  else if(page==='itinerarios')html=planner(params);
  else if(page==='perfil')html=profileView();
  else if(page==='ayuda')html=helpView();
  else if(page==='registro')html=profileFormView(params);
  else if(page==='preferencias')html=preferencesView(params);
  else if(['plan','solicitud','confirmacion'].includes(page)){
    const p=findPlan(id);if(p){currentPlan=p;html=page==='plan'?planView(p):page==='solicitud'?requestView(p):confirmationView(p);}else html=missingPlan();
  }else{html=home();screen='inicio';}
  const meta=SCREEN_ROUTES[screen];
  document.title=(screen==='destino'?destination(id).name:meta.label)+' · MYSTIGO';
  $('#main').innerHTML=html;$('#main').setAttribute('data-screen',screen);nav(meta.nav);$('#breadcrumb').textContent=meta.breadcrumb;
  if(page==='explorar')updateExplore();
  if(page==='itinerarios'&&$('#selected-activities')&&$('#plan-destination'))$('#selected-activities').innerHTML=selectedText($('#plan-destination').value);
  if(!storageAvailable)$('#main').insertAdjacentHTML('afterbegin','<p class="notice yellow">El almacenamiento no está disponible. Descarga tus planes para conservarlos.</p>');
  if(typeof renderEnhancements==='function')renderEnhancements();
}
function saveCurrent(show=true){if(!currentPlan)return;const i=state.plans.findIndex(p=>p.id===currentPlan.id);if(i<0)state.plans.unshift(currentPlan);else state.plans[i]=currentPlan;state.plans=state.plans.slice(0,40);if(persist()&&show)toast('Itinerario guardado en este navegador.');}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadPlan(){if(!currentPlan)return;const p=currentPlan,d=destination(p.dest);const text=`MYSTIGO — TU ITINERARIO\n${d.name}\n${dateLabel(p.date)} · ${p.days.length} días · ${p.people} persona(s)\nEstilo: ${p.style}\nEstado: ${p.status==='requested'?'Solicitud pendiente de pago':'Vista previa'}\n\n`+p.days.map((day,i)=>`DÍA ${i+1} — ${dateLabel(datePlus(p.date,i))}\n${day.title}\n`+day.items.map(a=>`${a.time} · ${a.name}\n${a.note}\nMapa: ${mapLink(a.name,d.name)}`).join('\n\n')).join('\n\n')+`\n\nPRESUPUESTO ESTIMADO DEL GRUPO: ${money(p.cost.total)}\nAlojamiento: ${money(p.cost.lodging)}\nAlimentación: ${money(p.cost.food)}\nActividades y movilidad local: ${money(p.cost.activities)}\nMargen: ${money(p.cost.reserve)}\nServicio de planificación por separado: S/ 15\nNo incluye pasajes, vuelos ni reservas especiales. No es una cotización ni una reserva.\nHorarios y accesos sujetos a confirmación.\n\n${d.tip}\nFuente turística: ${d.source}\n\nMYSTIGO · mytigo.maps@gmail.com\n`;download('Mystigo_'+d.id+'_itinerario.txt',text,'text/plain;charset=utf-8');toast('Tu itinerario se descargó. También puedes imprimirlo como PDF.');}
function requestView(p){
  const d=destination(p.dest);
  return `${pageBack('plan/'+p.id,'Volver a mi itinerario')}${title('TU VIAJE, BIEN ORGANIZADO','Revisa tu solicitud.','Conoce qué incluye la planificación y confirma los datos del viaje.')}
  ${flowSteps(['Revisa tu solicitud','Próximos pasos'],0)}
  <div class="request-layout"><div><section class="panel"><div class="request-destination"><img src="${d.image}" alt="${esc(d.photo)}"><div><span class="field-caption">TU PRÓXIMA PARADA</span><h2>${esc(d.name)}</h2><p>${esc(d.region)}, ${esc(d.country||'Perú')}</p></div></div><dl class="request-facts"><div><dt>Inicio del viaje</dt><dd>${dateLabel(p.date)}</dd></div><div><dt>Duración</dt><dd>${p.days.length} ${p.days.length===1?'día':'días'}</dd></div><div><dt>Viajeros</dt><dd>${p.people} ${p.people===1?'persona':'personas'}</dd></div><div><dt>Estilo</dt><dd>${esc(p.style)}</dd></div><div><dt>Presupuesto del grupo</dt><dd>${money(p.budget)}</dd></div><div><dt>Intereses</dt><dd>${p.interests.map(esc).join(', ')||'Un poco de todo'}</dd></div></dl><a href="#plan/${esc(p.id)}" class="text-link">Revisar mi recorrido ${icon('arrow')}</a></section><section class="panel"><h2>Lo que recibes por S/ 15.</h2><ul class="planner-benefits"><li>Actividades organizadas por día y un orden de visita</li><li>Horarios orientativos y recomendaciones para tu recorrido</li><li>Presupuesto estimado y ubicaciones de los lugares</li></ul><p>El servicio corresponde a la planificación del viaje. Entradas, pasajes, hospedaje, comidas y actividades se contratan por separado.</p></section></div><aside><section class="panel request-checkout"><div class="eyebrow">RESUMEN DEL SERVICIO</div><h2>Tu aventura,<br>bien encaminada.</h2><div class="summary-price"><span>Planificación personalizada</span><strong>S/ 15</strong></div><div class="notice yellow spacer-top">El pago está pendiente de coordinación. Esta web no realiza cobros ni reservas.</div><p class="storage-note">Guardar la solicitud la conserva en este navegador. En el siguiente paso podrás abrir tu correo y compartirla con Mystigo.</p><button class="button" data-action="confirm-request" data-id="${esc(p.id)}" style="width:100%">Guardar solicitud y continuar ${icon('arrow')}</button><a href="#plan/${esc(p.id)}" class="text-link spacer-top">Volver al itinerario</a></section></aside></div>`;
}
function requestMail(p){const body=`Hola, Mystigo. Quisiera coordinar el servicio de planificación de S/ 15.\n\nDestino: ${destination(p.dest).name}\nInicio: ${p.date}\nDías: ${p.days.length}\nPersonas: ${p.people}\nPresupuesto del grupo: ${money(p.budget)}\nIntereses: ${p.interests.join(', ')}\n\nPor favor, confírmenme la disponibilidad y el medio de pago.`;return 'mailto:mytigo.maps@gmail.com?subject=Solicitud%20de%20itinerario%20MYSTIGO&body='+encodeURIComponent(body);}
function confirmationView(p){
  if(p.status!=='requested')return `${title('TU PRÓXIMO PASO','Primero revisa tu solicitud.','Confirma los datos de tu viaje antes de continuar.')}<section class="panel"><p>Tienes una vista previa de tu itinerario. Para guardar una solicitud, revisa primero el resumen.</p><a class="button" href="#solicitud/${esc(p.id)}">Revisar solicitud ${icon('arrow')}</a></section>`;
  return `${pageBack('solicitud/'+p.id,'Volver al resumen')}${title('SOLICITUD GUARDADA EN ESTE DISPOSITIVO','Un paso más cerca de viajar.','Tu recorrido está preparado. Ahora puedes coordinar el servicio con Mystigo.')}
  ${flowSteps(['Revisa tu solicitud','Próximos pasos'],1)}
  <section class="panel confirmation-card"><span class="confirmation-icon">${icon('check')}</span><span class="pill">Pendiente de coordinación y pago</span><h2>Tu viaje a ${esc(destination(p.dest).name)}<br>ya tiene un primer plan.</h2><p>${dateLabel(p.date)} · ${p.days.length} días · ${p.people} persona(s)</p><div class="notice">La solicitud está guardada en este navegador. Todavía no se ha enviado y no se ha realizado ningún cobro.</div><ol class="next-steps"><li><span>1</span><div><h3>Comparte tu solicitud</h3><p>Abre tu correo, revisa el mensaje preparado y envíalo a Mystigo.</p></div></li><li><span>2</span><div><h3>Coordina los detalles</h3><p>Confirma la disponibilidad del servicio y el medio de pago con Mystigo.</p></div></li><li><span>3</span><div><h3>Lleva tu plan contigo</h3><p>Guarda o descarga tu recorrido y confirma cada reserva con el proveedor.</p></div></li></ol><div class="form-actions"><a href="${requestMail(p)}" class="button">Abrir correo con mi solicitud ${icon('arrow')}</a><button class="button outline" data-action="download-plan">${icon('download')}Descargar mi plan</button></div><div class="confirmation-links"><a href="#plan/${esc(p.id)}" class="text-link">Ver mi itinerario</a><a href="#itinerarios" class="text-link">Mis itinerarios</a><a href="#inicio" class="text-link">Volver al inicio</a></div><p class="storage-note">El borrador se dirige a mytigo.maps@gmail.com. Tú decides cuándo enviar el mensaje desde tu aplicación de correo.</p></section>`;
}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='close-modal')$('#modal').close();else if(a==='profile'){navigate(state.profile?'perfil':'registro?volver='+encodeURIComponent(safeReturn(location.hash.slice(1))));}else if(a==='register'){navigate('registro?volver='+encodeURIComponent(safeReturn(location.hash.slice(1))));}else if(a==='edit-profile'){navigate('registro?volver=perfil');}else if(a==='preferences'){navigate('preferencias?volver=perfil');}else if(a==='favorite'){const id=b.dataset.id;if(!destination(id))return;const i=state.favorites.indexOf(id);if(i<0)state.favorites.push(id);else state.favorites.splice(i,1);log(i<0?'destino_guardado':'favorito_retirado',destination(id).name);if(location.hash.startsWith('#favoritos'))render();else{$$(`[data-action="favorite"][data-id="${id}"]`).forEach(btn=>{btn.classList.toggle('saved',i<0);btn.setAttribute('aria-pressed',i<0);btn.setAttribute('aria-label',`${i<0?'Quitar':'Guardar'} ${destination(id).name} ${i<0?'de':'en'} favoritos`);});nav(location.hash.startsWith('#destino')?'explorar':(location.hash.slice(1).split('?')[0]||'inicio'));}toast(i<0?'Destino añadido a tus favoritos.':'Destino retirado de favoritos.');}else if(a==='home-category'){location.hash='explorar?categoria='+encodeURIComponent(b.dataset.category);}else if(a==='explore-category'){explore.category=b.dataset.category;updateExplore();}else if(a==='reset-filters'){location.hash='explorar';if(location.hash==='#explorar')render();}else if(a==='plan-interest'||a==='preference-choice'){b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');}else if(a==='select-activity'){const key=b.dataset.key;const i=state.selected.indexOf(key);if(i<0)state.selected.push(key);else state.selected.splice(i,1);persist();b.classList.toggle('selected',i<0);b.setAttribute('aria-pressed',i<0);b.textContent=i<0?'✓ Agregado':'+ Mi viaje';toast(i<0?'Lugar añadido a tu viaje. Se priorizará al planificar.':'Lugar retirado de tu selección.');}else if(a==='save-plan')saveCurrent();else if(a==='download-plan')downloadPlan();else if(a==='print-plan')window.print();else if(a==='request-plan'&&currentPlan){saveCurrent(false);navigate('solicitud/'+currentPlan.id);}else if(a==='confirm-request'){const p=findPlan(b.dataset.id);if(!p)return;currentPlan=p;const first=p.status!=='requested';p.status='requested';p.requestedAt=p.requestedAt||new Date().toISOString();saveCurrent(false);if(first)log('solicitud_pendiente',destination(p.dest).name);navigate('confirmacion/'+p.id);}else if(a==='move-item'&&currentPlan){const di=Number(b.dataset.day),i=Number(b.dataset.item),j=i+Number(b.dataset.direction),items=currentPlan.days[di]?.items;if(!items||j<0||j>=items.length)return;const times=items.map(x=>x.time);[items[i],items[j]]=[items[j],items[i]];items.forEach((x,n)=>x.time=times[n]);if(state.plans.some(p=>p.id===currentPlan.id))saveCurrent(false);render();}else if(a==='remove-item'&&currentPlan){const items=currentPlan.days[Number(b.dataset.day)]?.items;if(!items||items.length<=1){toast('Conserva al menos una actividad en cada día.');return;}items.splice(Number(b.dataset.item),1);if(state.plans.some(p=>p.id===currentPlan.id))saveCurrent(false);render();toast('Actividad retirada. Los importes siguen siendo estimaciones diarias.');}else if(a==='delete-plan'){openModal(`<h2>¿Eliminar este itinerario?</h2><p>Se quitará de los planes guardados en este navegador.</p><button class="button danger" data-action="confirm-delete-plan" data-id="${esc(b.dataset.id)}">Eliminar itinerario</button>`);}else if(a==='confirm-delete-plan'){state.plans=state.plans.filter(p=>p.id!==b.dataset.id);if(currentPlan?.id===b.dataset.id)currentPlan=null;persist();$('#modal').close();render();toast('Itinerario eliminado.');}else if(a==='export-data'){download('Mystigo_mis_datos.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');}else if(a==='reset-data'){openModal('<h2>¿Borrar tus datos locales?</h2><p>Se eliminarán el perfil, las preferencias, los favoritos, los planes y las opiniones de este navegador. Descarga tus datos antes si deseas conservarlos.</p><div class="form-actions"><button class="button outline" data-action="export-data">Descargar mis datos</button><button class="button danger" data-action="confirm-reset">Borrar datos locales</button></div>');}else if(a==='confirm-reset'){state=defaults();currentPlan=null;persist();$('#modal').close();render();toast('Tus datos locales se borraron.');}else if(a==='rating'){const n=Number(b.dataset.rating);$('#opinion-form [name="rating"]').value=n;$$('.rating button').forEach(x=>{x.classList.toggle('selected',Number(x.dataset.rating)<=n);x.setAttribute('aria-pressed',Number(x.dataset.rating)===n);});}});
document.addEventListener('input',e=>{if(e.target.id==='explore-query'){explore.q=e.target.value;updateExplore();}});
document.addEventListener('change',e=>{if(e.target.id==='explore-zone'){explore.zone=e.target.value;updateExplore();}else if(e.target.id==='explore-budget'){explore.budget=e.target.value;updateExplore();}else if(e.target.id==='plan-destination')$('#selected-activities').innerHTML=selectedText(e.target.value);});
document.addEventListener('submit',e=>{const form=e.target;if(!['home-search','planner-form','profile-form','preferences-form','opinion-form'].includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);if(form.id==='home-search'){const q=String(f.get('query')||'').trim(),c=f.get('category');log('busqueda',q||c);location.hash='explorar?q='+encodeURIComponent(q)+'&categoria='+encodeURIComponent(c);}else if(form.id==='planner-form')createPlan(form);else if(form.id==='profile-form'){
  const name=String(f.get('name')||'').trim(),email=String(f.get('email')||'').trim();
  if(!name){toast('Escribe tu nombre para crear el perfil.');return;}
  const exists=!!state.profile,back=safeReturn(form.dataset.return,exists?'perfil':'inicio');
  state.profile={name,email};log(exists?'perfil_actualizado':'perfil_creado',name);
  navigate(exists?back:'preferencias?volver='+encodeURIComponent(back));
  if(exists)toast('Perfil actualizado en este navegador.');
}else if(form.id==='preferences-form'){
  if(!$$('[data-choice-group] .choice[aria-pressed="true"]',form).length){toast('Elige al menos un gusto o una actividad para personalizar tus viajes.');return;}
  state.prefs={types:$$('[data-choice-group="types"] .choice[aria-pressed="true"]',form).map(b=>b.dataset.value),activities:$$('[data-choice-group="activities"] .choice[aria-pressed="true"]',form).map(b=>b.dataset.value),company:f.get('company'),budget:f.get('budget'),...readTravelPreferences(f),configured:true};
  log('preferencias_actualizadas',state.prefs.types.join(', '));
  navigate(safeReturn(form.dataset.return));toast('Listo. Tus recomendaciones ya tienen tu estilo.');
}else if(form.id==='opinion-form'){const rating=Number(f.get('rating'));if(rating<1||rating>5){toast('Elige una calificación de 1 a 5 estrellas.');return;}const name=String(f.get('name')).trim(),message=String(f.get('message')).trim();if(!name||!message){toast('Completa tu nombre y comentario.');return;}state.opinions.unshift({name,message,rating,at:new Date().toISOString()});state.opinions=state.opinions.slice(0,30);log('opinion_guardada',`${rating}/5`);render();toast('Opinión guardada en este navegador. Puedes compartirla por correo.');}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
function hasSavedTravelPreferences(){return state.prefs.configured===true||((Array.isArray(state.prefs.types)&&state.prefs.types.length||Array.isArray(state.prefs.activities)&&state.prefs.activities.length)&&Number(state.prefs.tripBudget)>=50);}
function restoreEntryScreen(){if(!hasSavedTravelPreferences()&&location.hash!=='#inicio')history.replaceState(null,'','#inicio');}
window.addEventListener('pageshow',event=>{if(event.persisted){restoreEntryScreen();render();}});
restoreEntryScreen();
render();
